<?php
function s3_status($response,$status){m0_assert(wp_remote_retrieve_response_code($response)===$status,'HTTP '.wp_remote_retrieve_response_code($response).' expected '.$status.': '.substr(strip_tags(preg_replace('~<style.*?</style>~s','',wp_remote_retrieve_body($response))),-450));}
function s3_assignment($id=999232){global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}survey_assignments WHERE id=%d",$id),ARRAY_A);}
function s3_legacy($data=array(),$admin=true){$query=array_merge(array('page'=>'eipsi-results','action'=>'export_participants_excel','study_id'=>999203,'_wpnonce'=>m0_admin_nonce('eipsi_admin_nonce')),$data);return m0_http('/wp-admin/admin.php?'.http_build_query($query),null,$admin);}
function s3_trace(){return json_decode(file_get_contents('/tmp/eipsi-s3-http-trace.json'),true);}
