$tests['Reminder authenticated subscriber rejected']=function(){global $wpdb;$id=wp_insert_user(array('user_login'=>'s3-subscriber','user_pass'=>'s3-fixture','user_email'=>'s3-subscriber@example.invalid','role'=>'subscriber'));m0_assert(!is_wp_error($id),'Subscriber');try{$token=WP_Session_Tokens::get_instance($id)->create(time()+600);$cookie=wp_generate_auth_cookie($id,time()+600,'logged_in',$token);wp_set_current_user($id);$nonce=wp_create_nonce('eipsi_study_dashboard_nonce');wp_set_current_user(1);$r=wp_remote_post('http://127.0.0.1/wp-admin/admin-ajax.php',array('headers'=>array('Host'=>'127.0.0.1:18080','Cookie'=>LOGGED_IN_COOKIE.'='.$cookie),'body'=>array('action'=>'eipsi_send_individual_reminder','participant_id'=>999207,'wave_id'=>999222,'nonce'=>$nonce),'timeout'=>20));s3_status($r,403);}finally{require_once ABSPATH.'wp-admin/includes/user.php';wp_delete_user($id);}};
