$tests['Reminder delivery failure reported with persisted failed log']=function(){global $wpdb;update_option('eipsi_s3_mail_failure',true);$j=s3_json(s3_request('eipsi_send_individual_reminder',array('participant_id'=>999207,'wave_id'=>999222)));m0_assert(!$j['success']&&$j['data']['sent_count']===0&&$j['data']['failed_count']===1,'Delivery false success');m0_assert($wpdb->get_var("SELECT status FROM {$wpdb->prefix}survey_email_log WHERE survey_id=999203 ORDER BY id DESC LIMIT 1")==='failed','Failed log missing');};
