$tests['Preview HTTP has zero domain mutations and cron unchanged']=function(){$before=s3_assignment();$cron=get_option('cron');$j=s3_json(s3_request('eipsi_recalculate_preview',array('study_id'=>999203)));m0_assert($j['success']&&s3_assignment()===$before&&s3_trace()===array(),'Preview wrote domain');wp_cache_delete('alloptions','options');m0_assert(get_option('cron')===$cron,'Preview scheduled cron');};
$tests['Preview direct owner performs only reads']=function(){$writes=array();$filter=function($sql)use(&$writes){if(preg_match('/^\s*(INSERT|UPDATE|DELETE|REPLACE|ALTER|CREATE|DROP)/i',$sql)){$writes[]=$sql;}return $sql;};add_filter('query',$filter);try{$r=EIPSI_Longitudinal_T1_Recalculation_Service::preview_study(999203);}finally{remove_filter('query',$filter);}m0_assert(!is_wp_error($r)&&$writes===array(),'Owner preview writes');};
