$tests['Apply HTTP delegates minute offsets and preserves T1']=function(){$t1=s3_assignment(999231);$j=s3_json(s3_request('eipsi_recalculate_waves',array('study_id'=>999203)));$a=s3_assignment();m0_assert($j['success']&&$j['data']['waves_to_update']===2&&isset($j['data']['message']),'Apply shape');m0_assert($a['available_at']===date('Y-m-d H:i:s',strtotime($GLOBALS['s3_anchor'])+2880*60)&&$a['due_at']===date('Y-m-d H:i:s',strtotime($a['available_at'])+30*60),'Arithmetic changed');m0_assert(s3_assignment(999231)===$t1,'T1 modified');};
$tests['Apply leaves submitted skipped expired dates intact']=function(){global $wpdb;foreach(array('submitted','skipped','expired')as$status){$wpdb->update($wpdb->prefix.'survey_assignments',array('status'=>$status),array('id'=>999233));$before=s3_assignment(999233);$j=s3_json(s3_request('eipsi_recalculate_waves',array('study_id'=>999203)));m0_assert($j['success']&&s3_assignment(999233)===$before,'Terminal rewritten');}};
