$tests['Apply audit includes old new values and admin actor']=function(){global $wpdb;$j=s3_json(s3_request('eipsi_recalculate_waves',array('study_id'=>999203)));$row=$wpdb->get_row("SELECT * FROM {$wpdb->prefix}survey_audit_log WHERE survey_id=999203 ORDER BY id DESC LIMIT 1");$metadata=json_decode($row->metadata,true);m0_assert($j['success']&&$row->actor_type==='admin'&&(int)$row->actor_id===1&&isset($metadata['old_value'],$metadata['new_value'],$metadata['batch_id']),'Audit contract');};
$tests['Apply cron refresh occurs after COMMIT']=function(){$j=s3_json(s3_request('eipsi_recalculate_waves',array('study_id'=>999203)));$trace=s3_trace();$commit=array_search('COMMIT',$trace,true);$queue=array_search('UPDATE:survey_nudge_jobs',$trace,true);m0_assert($j['success']&&$commit!==false&&$queue!==false&&$commit<$queue,'Refresh before commit');};
