$tests['Legacy XLSX valid stream columns and canonical filename']=function(){$r=s3_legacy();s3_status($r,200);$body=wp_remote_retrieve_body($r);m0_assert(substr($body,0,2)==='PK','XLSX not ZIP');m0_assert(strpos(wp_remote_retrieve_header($r,'content-type'),'spreadsheetml')!==false&&strpos(wp_remote_retrieve_header($r,'content-disposition'),'participantes-wide-999203-')!==false,'Stream headers');$tmp=tempnam('/tmp','s3-xlsx-');file_put_contents($tmp,$body);$zip=new ZipArchive();try{m0_assert($zip->open($tmp)===true,'ZIP');$xml=$zip->getFromName('xl/worksheets/sheet1.xml').$zip->getFromName('xl/sharedStrings.xml');m0_assert(strpos($xml,'Email')!==false&&strpos($xml,'T1')!==false&&strpos($xml,'T1_submitted_at')!==false,'Expected columns missing');}finally{$zip->close();unlink($tmp);}};
