$tests['Legacy XLSX filters apply to existing roster']=function(){$r=s3_legacy(array('search'=>'s3-999207'));s3_status($r,200);$tmp=tempnam('/tmp','s3-xlsx-');file_put_contents($tmp,wp_remote_retrieve_body($r));$zip=new ZipArchive();try{m0_assert($zip->open($tmp)===true,'ZIP');$xml=$zip->getFromName('xl/worksheets/sheet1.xml').$zip->getFromName('xl/sharedStrings.xml');m0_assert(strpos($xml,'s3-999207')!==false&&strpos($xml,'s3-999208')===false,'Filter ignored');}finally{$zip->close();unlink($tmp);}};
$tests['LONG remains unresolved without aliases']=function(){m0_assert(!has_action('wp_ajax_eipsi_export_participants_long_excel')&&!has_action('wp_ajax_eipsi_export_participants_long_csv'),'Invented LONG');$source=file_get_contents(EIPSI_FORMS_PLUGIN_DIR.'admin/tabs/export-tab.php');m0_assert(strpos($source,'id="ep-download-excel-long"')===false&&strpos($source,'id="ep-download-csv-long"')===false,'LONG UI falsely restored');};
