require __DIR__.'/concurrency.php';
$tests['Apply waits on real assignment lock and rereads terminal status']=function(){$before=s3_assignment();$results=s3_concurrent(array('apply'),array('status'=>'submitted'));$after=s3_assignment();m0_assert($results[0]['result']['waves_to_update']===1&&$after['status']==='submitted'&&$after['available_at']===$before['available_at']&&$after['due_at']===$before['due_at'],'Stale recalc overwrote terminal');};
$tests['Two real apply workers serialize without stale audit dates']=function(){global $wpdb;$results=s3_concurrent(array('apply','apply'));foreach($results as$r){m0_assert(!isset($r['result']['error'])&&$r['result']['waves_to_update']===2,'Concurrent apply failed');}$audit=$wpdb->get_results("SELECT metadata FROM {$wpdb->prefix}survey_audit_log WHERE survey_id=999203 ORDER BY id");$count=0;foreach($audit as$row){$m=json_decode($row->metadata,true);if((int)$m['wave_id']===999222){$count++;if($count===2){m0_assert($m['old_value']===$m['new_value'],'Second worker stale audit');}}}m0_assert($count===2,'Audit count');};
$tests['Concurrent submit and apply preserve submitted outcome']=function(){global $wpdb;$wpdb->update($wpdb->prefix.'survey_waves',array('offset_minutes'=>1430),array('id'=>999222));$results=s3_concurrent(array('apply','submit'));m0_assert(s3_assignment()['status']==='submitted','Lost submission: '.wp_json_encode($results));foreach($results as$r){m0_assert(!isset($r['result']['error']),'Concurrent mutation failed');}};
foreach(array('update','audit')as$operation){$tests['Apply '.$operation.' SQL failure rolls back assignment']=function()use($operation){global $wpdb;$before=s3_assignment();$fired=false;$filter=function($sql)use($operation,&$fired){$match=$operation==='update'?preg_match('/^UPDATE.*survey_assignments.*available_at/is',$sql):preg_match('/^INSERT.*survey_audit_log/is',$sql);if($match&&!$fired){$fired=true;return 'SELECT eipsi_s3_controlled_missing_column';}return $sql;};$wpdb->suppress_errors(true);add_filter('query',$filter);try{$r=EIPSI_Longitudinal_T1_Recalculation_Service::recalculate_study(999203,1);}finally{remove_filter('query',$filter);$wpdb->suppress_errors(false);}m0_assert($fired&&is_wp_error($r)&&$r->get_error_data()['updated']===0&&s3_assignment()===$before,'Failed recalc persisted');};}
$tests['Postcommit refresh failure reports persisted partial result']=function(){global $wpdb;$before=s3_assignment();$fired=false;$filter=function($sql)use(&$fired){if(!$fired&&preg_match('/^UPDATE.*survey_nudge_jobs/is',$sql)){$fired=true;return 'SELECT eipsi_s3_controlled_missing_column';}return $sql;};$wpdb->suppress_errors(true);add_filter('query',$filter);try{$r=EIPSI_Longitudinal_T1_Recalculation_Service::recalculate_study(999203,1);}finally{remove_filter('query',$filter);$wpdb->suppress_errors(false);}m0_assert($fired&&is_wp_error($r)&&$r->get_error_code()==='refresh_failed'&&$r->get_error_data()['updated']===1&&s3_assignment()['available_at']!==$before['available_at'],'Partial result hidden');};
foreach(json_decode(file_get_contents(__DIR__.'/consumer-requests.json'),true)as$key=>$fixture){$tests['Executed JS fixture to HTTP handler owner response: '.$key]=function()use($key,$fixture){$participant=in_array($key,array('wave','dashboard'),true);$r=s3_request($fixture['action'],$fixture['data'],!$participant,$participant?s3_session():null,$fixture['nonce_action']);s3_status($r,200);$j=s3_json($r);m0_assert($j['success'],'Actual JS request failed');if($key==='preview'){m0_assert($j['data']===array('affected_participants'=>1,'waves_to_update'=>2),'Preview response');}elseif($key==='dashboard'){m0_assert($j['data']['progress_percentage']===33,'Dashboard render field');}elseif($key==='reminder'){m0_assert($j['data']['sent_count']===1,'Actual reminder failed');}elseif($key==='apply'){m0_assert(isset($j['data']['message'])&&$j['data']['waves_to_update']===2,'Apply render field');}else{m0_assert($j['data']['wave_name']==='S3 T2','Polling response');}};}
